files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --pixel-border: 4px solid #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, #1f1f3a 25%, transparent 25%),
    linear-gradient(-45deg, #1f1f3a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #1f1f3a 75%),
    linear-gradient(-45deg, transparent 75%, #1f1f3a 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background-color: var(--card);
  border: var(--pixel-border);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(233, 69, 96, 0.3);
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 24px;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
}

.mode-btn {
  background: transparent;
  border: 3px solid var(--muted);
  color: var(--muted);
  font-family: inherit;
  font-size: 1rem;
  padding: 8px 16px;
  cursor: pointer;
  transition: all 0.1s;
  border-radius: 0;
}

.mode-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.mode-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.mode-btn:active {
  transform: translate(2px, 2px);
}

.countdown {
  font-family: 'Courier New', monospace;
  font-size: 5rem;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 24px 0;
  color: var(--text);
  text-shadow: 4px 4px 0 #000;
  line-height: 1;
  word-break: break-word;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

.btn {
  background: transparent;
  border: 3px solid var(--muted);
  color: var(--text);
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 20px;
  cursor: pointer;
  transition: all 0.1s;
  border-radius: 0;
  min-width: 80px;
}

.btn:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(233, 69, 96, 0.1);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn.primary:hover:not(:disabled) {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  color: #fff;
}

.hint {
  font-size: 0.875rem;
  color: var(--muted);
  margin-top: 8px;
}

@media (max-width: 400px) {
  .countdown {
    font-size: 3.5rem;
  }
  .card {
    padding: 24px 16px;
  }
  .btn {
    padding: 10px 14px;
    min-width: 70px;
  }
  .mode-btn {
    padding: 6px 12px;
  }
}

(function () {
  'use strict';

  const WORK_TIME = 25 * 60;
  const BREAK_TIME = 5 * 60;

  let currentMode = 'work';
  let timeLeft = WORK_TIME;
  let timerId = null;
  let isRunning = false;

  const display = document.getElementById('timer-display');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const resetBtn = document.getElementById('reset-btn');
  const workModeBtn = document.getElementById('work-mode');
  const breakModeBtn = document.getElementById('break-mode');

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function render() {
    display.textContent = formatTime(timeLeft);
    startBtn.disabled = isRunning;
    pauseBtn.disabled = !isRunning;
  }

  function setMode(mode) {
    if (isRunning) return;
    currentMode = mode;
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    workModeBtn.classList.toggle('active', mode === 'work');
    breakModeBtn.classList.toggle('active', mode === 'break');
    workModeBtn.setAttribute('aria-pressed', mode === 'work');
    breakModeBtn.setAttribute('aria-pressed', mode === 'break');
    render();
  }

  function tick() {
    timeLeft -= 1;
    if (timeLeft <= 0) {
      stopTimer();
      timeLeft = 0;
      render();
      const nextMode = currentMode === 'work' ? 'break' : 'work';
      setMode(nextMode);
      return;
    }
    render();
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    timerId = setInterval(tick, 1000);
    render();
  }

  function pauseTimer() {
    if (!isRunning) return;
    stopTimer();
    render();
  }

  function stopTimer() {
    clearInterval(timerId);
    timerId = null;
    isRunning = false;
  }

  function resetTimer() {
    stopTimer();
    timeLeft = currentMode === 'work' ? WORK_TIME : BREAK_TIME;
    render();
  }

  startBtn.addEventListener('click', startTimer);
  pauseBtn.addEventListener('click', pauseTimer);
  resetBtn.addEventListener('click', resetTimer);
  workModeBtn.addEventListener('click', () => setMode('work'));
  breakModeBtn.addEventListener('click', () => setMode('break'));

  document.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'BUTTON') return;
    if (e.code === 'Space') {
      e.preventDefault();
      if (isRunning) pauseTimer();
      else startTimer();
    } else if (e.key === 'r' || e.key === 'R') {
      resetTimer();
    }
  });

  render();
})();
